<template>
  <div class="saved-filter-badge row absolute">
    <template v-for="[key, value] in quickFilterMap" :key="key">
      <template v-if="key == 'order_status'">
        <q-badge rounded color="primary" class="q-mr-sm capitalize">
          <template v-slot>
            {{ $t(value.value) }}
            <q-icon
              name="close"
              color="white"
              size="xs"
              class="q-ml-xs cursor-pointer"
              style="font-size: 12px !important"
              @click="removeFilter(key)"
            />
          </template>
        </q-badge>
      </template>
      <q-badge rounded color="primary" class="q-mr-sm capitalize" v-else>
        {{ value }}
        <q-icon
          name="close"
          color="white"
          class="q-ml-xs cursor-pointer"
          size="xs"
          style="font-size: 12px !important"
          @click="removeFilter(key)"
        />
      </q-badge>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useDashboardStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { usePoAndInvoiceStore } from 'src/supplier/store';

export default defineComponent({
  props: {},
  mounted() {
    this.init();
  },
  methods: {
    async init() {
      await this.$nextTick();
    },

    removeFilter(key: string) {
      this.quickFilterMap.delete(key);
      if (key in this.params) {
        this.params[key as keyof typeof this.params] = '';
      }
      this.getDataServer();
    },
    async getDataServer() {
      try {
        this.loading = true;
        await this.getPurchaseOrderData();
      } catch (err) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
  setup() {
    const store = storeToRefs(usePoAndInvoiceStore());
    const { getPurchaseOrderData } = usePoAndInvoiceStore();
    const { params, quickFilterMap, loading } = store;
    return {
      quickFilterMap,
      params,
      loading,
      getPurchaseOrderData,
    };
  },
});
</script>
