<template>
  <q-input
    outlined
    dense
    v-model="params.before_date"
    @update:model-value="fetchData"
    :clearable="true"
    class="q-mr-sm"
    style="width: 227px; height: 40px"
  >
    <template v-slot:append>
      <q-icon name="event" class="cursor-pointer">
        <q-popup-proxy cover transition-show="scale" transition-hide="scale">
          <q-date
            @update:model-value="fetchData"
            v-model="params.before_date"
            mask="YYYY-MM-DD"
          >
            <div class="row items-center justify-end">
              <q-btn v-close-popup label="Close" color="primary" flat />
            </div>
          </q-date>
        </q-popup-proxy>
      </q-icon>
    </template>
  </q-input>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { usePoAndInvoiceStore } from 'src/supplier/store';
export default defineComponent({
  mixins: [],
  props: {},
  watch: {
    'params.before_date': {
      deep: true,
      handler: function (newVal, oldVal) {
        this.handleQuikFilter();
      },
    },
  },
  methods: {
    fetchData(value: any) {
      this.params.before_date = value;
      this.resetPagination();
      this.getPurchaseOrderData();
    },
    handleQuikFilter() {
      if (
        this.params.before_date === null ||
        this.params.before_date.trim() === ''
      ) {
        this.quickFilterMap.delete('before_date');
      } else {
        this.quickFilterMap.set('before_date', this.params.before_date);
      }
    },
  },
  setup() {
    const date = ref();
    const store = storeToRefs(usePoAndInvoiceStore());
    const { getPurchaseOrderData, resetPagination } = usePoAndInvoiceStore();
    const { params, quickFilterMap } = store;
    return {
      resetPagination,
      getPurchaseOrderData,
      params,
      date,
      quickFilterMap,
    };
  },
});
</script>
