<template>
  <q-input
    class="width-500"
    dense
    v-model="params.keyword"
    autofocus
    :placeholder="$t('search_by_po_number')"
    outlined
    @keyup="onKeyup"
  >
    <template v-slot:append>
      <f-btn icon="tune" appearance="flat">
        <q-menu
          style="width: 500px; min-height: 250px"
          anchor="bottom start"
          self="top left"
          :offset="[453, 10]"
        >
          <div class="q-pa-md">
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('before_date') }}</span>
              <q-space />
              <BeforeDate />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('after_date') }}</span>
              <q-space />
              <AfterDate />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('status') }}</span>
              <q-space />
              <Status />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('max_amount') }}</span>
              <q-space />
              <MaxAmount />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('min_amount') }}</span>
              <q-space />
              <MinAmount />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{ $t('pagination_size') }}</span>
              <q-space />
              <q-select
                outlined
                dense
                class="q-mr-sm user-select"
                v-model="pagination.page_size"
                :options="pagination_options"
                @update:model-value="getPurchaseOrderData"
                :label="$t('pagination_size')"
              >
              </q-select>
            </div>
            <div class="float-right q-ml-auto">
              <f-btn
                appearance="secondary"
                class="q-mr-sm mt-20 q-mb-md"
                :label="$t('clear_filters')"
                @click="resetFilters()"
              />
            </div>
          </div>
        </q-menu>
      </f-btn>
    </template>
  </q-input>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { usePoAndInvoiceStore } from 'src/supplier/store/index';
import type { dynamicObj } from 'src/pages/assets';
import MinAmount from 'src/supplier/components/purchaseOrder/filter/min_amount-filter.vue';
import MaxAmount from 'src/supplier/components/purchaseOrder/filter/max_amount-filter.vue';
import Status from 'src/supplier/components/purchaseOrder/filter/status-filter.vue';
import BeforeDate from './before_date-filter.vue';
import AfterDate from './after_date-filter.vue';

export default defineComponent({
  mixins: [],
  props: {},
  components: {
    MaxAmount,
    MinAmount,
    Status,
    BeforeDate,
    AfterDate,
  },
  methods: {
    resetFilters() {
      this.quickFilterMap.clear();
      this.resetFilter();
      this.fetchData();
    },
    onKeyup(event: any) {
      if (event.key == 'Enter') {
        if (this.params.keyword.trim() === '') {
          this.quickFilterMap.delete('keyword');
        } else {
          this.quickFilterMap.set('keyword', this.params.keyword);
        }
        this.fetchData();
      }
    },
    async fetchData() {
      this.loading = true;
      this.resetPagination();
      await this.getPurchaseOrderData();
      this.loading = false;
    },

    handleEmptyStatus() {
      if (
        !(
          !this.searchInput ||
          this.searchInput === null ||
          this.searchInput.trim() === ''
        )
      ) {
        return false;
      }

      this.resetFilters();
      return true;
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },
    validatePaginationSize() {
      if (this.pagination.page_size <= 50) return;
      this.pagination.page_size = 50;
    },
  },

  mounted() {
    this.validatePaginationSize();
  },
  setup() {
    const dashboard_store = usePoAndInvoiceStore();
    const pagination_options = ['10', '20', '25', '50'];
    const { loading, pagination, params, quickFilterMap } =
      storeToRefs(dashboard_store);
    const { getPurchaseOrderData, resetPagination, resetFilter } =
      dashboard_store;

    return {
      getPurchaseOrderData,
      pagination,
      loading,
      searchInput: ref(''),
      oldSearchInput: ref(''),
      showing: ref(false),
      debounceSearchInputFunc: {} as any,
      request_params: {} as dynamicObj,
      filter_data_json_str: '',
      pagination_options,
      resetPagination,
      resetFilter,
      params,
      quickFilterMap,
    };
  },
});
</script>
<style lang="scss">
.search-invoices {
  width: 500px;
  padding: 0;
  transition: 0.3s;
}
.user-select {
  width: 227px;
}
</style>
