<template>
  <q-select
    outlined
    class="q-mr-sm"
    style="width: 227px; height: 40px"
    clearable
    dense
    v-model="params.order_status"
    :options="status"
    :label="$t('status')"
    @update:model-value="fetchData"
  >
    <template v-slot:selected-item="scope">
      <div>{{ scope.opt.label }}</div>
    </template>
  </q-select>
</template>

<script lang="ts">
// @ts-nocheck
import { defineComponent, ref } from 'vue';
import { PO_STATUSES } from 'src/pages/PurchaseOrders/constants.js';
import { usePoAndInvoiceStore } from 'src/supplier/store';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
export default defineComponent({
  mixins: [],
  props: {},
  mounted() {
    this.initStatus();
  },
  unmounted: function () {
    // document.removeEventListener('reset_filters', this.resetFilters);
  },
  data() {
    return {
      status: [] as any,
      PO_STATUSES,
    };
  },
  methods: {
    fetchData() {
      this.params.order_status
        ? this.quickFilterMap.set('order_status', this.params.order_status)
        : this.quickFilterMap.delete('order_status');
      this.resetPagination();
      this.getPurchaseOrderData();
    },
    initStatus() {
      this.status = [];
      for (const [key, item] of Object.entries(this.PO_STATUSES)) {
        this.status.push({
          label: this.$t(item.label),
          value: item.value,
        });
      }
    },
  },
  setup() {
    const store = storeToRefs(usePoAndInvoiceStore());
    const { getPurchaseOrderData, resetPagination } = usePoAndInvoiceStore();
    const { params, quickFilterMap } = store;
    return {
      params,
      getPurchaseOrderData,
      resetPagination,
      quickFilterMap,
    };
  },
});
</script>
<style lang="scss">
.select-box.doc-type-select {
  max-width: 260px;
}
</style>
