<template>
  <div class="row q-mb-md">
    <div class="col">
      <div
        class="row justify-start dashboard-title dark-readable"
        style="align-items: center"
      >
        <div class="q-ml-lg cursor-pointer mt-20" @click="getAllPO">
          {{ $t('all') }} ({{ statusCounts.all ? statusCounts.all : 0 }})
        </div>
        <div
          class="example-cell q-ml-lg cursor-pointer mt-20"
          @click="getFilterStatus('Open')"
        >
          {{ $t('open') }} ({{ statusCounts.open ? statusCounts.open : 0 }})
        </div>
        <div
          class="example-cell q-ml-lg cursor-pointer mt-20"
          @click="getFilterStatus('Invoiced')"
        >
          {{ $t('invoiced') }} ({{
            statusCounts.invoiced ? statusCounts.invoiced : 0
          }})
        </div>
        <div
          class="example-cell q-ml-lg cursor-pointer mt-20"
          @click="getFilterStatus('Received')"
        >
          {{ $t('received') }} ({{
            statusCounts.received ? statusCounts.received : 0
          }})
        </div>
        <div
          class="example-cell q-ml-lg cursor-pointer mt-20"
          @click="getFilterStatus('Closed')"
        >
          {{ $t('closed') }} ({{
            statusCounts.closed ? statusCounts.closed : 0
          }})
        </div>
        <div class="dashboard-search-box q-ml-md mt-20 white-inputs">
          <quickSearch />
        </div>
        <q-space />
        <f-btn
          square
          class="q-mr-sm mt-20"
          @click="refreshFilters"
        >
          <Icon icon="mdi:refresh" width="20" height="20" />
          <q-tooltip>{{ $t('refresh_list') }}</q-tooltip>
        </f-btn>
      </div>
    </div>
  </div>
  <div
    class="row mb-25 relative-position"
    style="margin-bottom: 8px"
    v-if="quickFilterMap.size > 0"
  >
    <div class="dashboard-toggler-area"></div>
    <savedFilterBadges />
  </div>
</template>
<script lang="ts">

import { defineComponent, ref } from 'vue';
import quickSearch from './filter/quick-search.vue';
import { storeToRefs } from 'pinia';
import { usePoAndInvoiceStore } from '../../store/index';
import type { dynamicObj } from 'src/pages/assets';
import savedFilterBadges from './saved-filter-badges.vue';
export default defineComponent({
  props: {
    type_name: {
      type: String,
      reqired: true,
      default: 'supplier',
    },
  },
  components: {
    
    quickSearch,
    savedFilterBadges,
  },
  mounted() {
    document.addEventListener('delete_input_text', this.clearSearchInput);
  },
  methods: {
    getFilterStatus(status: string) {
      logInfo(status, 'getFilterStatus');
      const stt = { label: status, value: status.toLowerCase() };
      this.params.order_status = stt as any;
      this.quickFilterMap.set('order_status', this.params.order_status);
      this.resetPagination();
      this.getDataServer();
    },
    getAllPO() {
      this.quickFilterMap.clear();
      this.resetFilter();
      this.resetPagination();
      this.getDataServer();
    },
    clearSearchInput() {
      this.searchInput = '';
    },
    refreshFilters() {
      this.getDataServer();
    },
    async getDataServer() {
      try {
        this.loading = true;
        await this.getPurchaseOrderData();
        this.total_records = this.paginationCount;
      } catch (err) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    resetFilters() {
      const event = new CustomEvent('reset_filters', {});
      document.dispatchEvent(event);
    },
  },
  setup() {
    const dashboard_purchase_order_store = usePoAndInvoiceStore();
    const {
      loading,
      display_data,
      params,
      pagination,
      paginationCount,
      quickFilterMap,
      statusCounts,
    } = storeToRefs(dashboard_purchase_order_store);
    const { getPurchaseOrderData, resetPagination, resetFilter } =
      dashboard_purchase_order_store;

    return {
      getPurchaseOrderData,
      searchInput: ref(''),
      display_data,
      loading,
      params,
      pagination,
      total_records: ref(0),
      paginationCount,
      quickFilterMap,
      resetPagination,
      resetFilter,
      statusCounts,
    };
  },
});
</script>
<style lang="scss">
.p-4-8 {
  padding: 4px 8px;
}
.search-invoices {
  width: 500px;
  padding: 0;
  transition: 0.3s;
}
</style>
