<template>
<MessageBanner v-if="!user_settings[po_dashboard]" :dissmiss_btn="false" :back_route="false" :message="$t('ACTION_NOT_ALLOWED')"  />
<template v-else>
  <SubHeader name="purchase_order" :label="$t('po_dashboard')">
  </SubHeader>

  <div class="dashboard-container dashboard-text-color dashboard-main" data-test="purchase-order-dashboard">
    <PoDashboardHeader />
    <q-separator class="seperator" />
    <div class="full-width dashboard-list-area q-my-lg" style="overflow-x: auto;">
      <DocBitsTable
        :rows="tableRows"
        :columns="v2TableColumns"
        row-key="id"
        table-id="purchase_order_table"
        :loading="loading"
        :features="v2TableFeatures"
        :row-actions="v2RowActions"
        :pagination="v2PaginationState"
        :rows-per-page-options="[10, 20, 25, 50]"
        pagination-label="po_pagination_size"
        :pagination-settings-key="pagination_settings_key"
        no-data-label="NO_RECORD_FOUND"
        :column-order="v2ColumnOrder"
        table-class="scroll-height-100vh-265px"
        @update:sorting="handleV2Sort"
        @update:pagination="handleV2Pagination"
        @column-reorder="handleV2ColumnReorder"
        @row-click="handleV2RowClick"
        @row-action="handleV2RowAction"
      >
        <!-- Order Date Column -->
        <template #body-cell-order_date="{ row }">
          {{ row.order_date ? formatDateTimeZone(row.order_date, true) : '' }}
        </template>

        <!-- Requested Shipment Date Column -->
        <template #body-cell-requested_shipment_date="{ row }">
          {{ row.requested_shipment_date ? formatDateTimeZone(row.requested_shipment_date, true) : '' }}
        </template>

        <!-- Status Column -->
        <template #body-cell-status="{ row }">
          <q-badge v-if="row.status" transparent align="middle" :color="statusColor(row.status)">
            {{ row.status }}
          </q-badge>
        </template>

        <!-- Total Amount Column -->
        <template #body-cell-total_amount="{ row }">
          <div align="right" style="padding-right: 10px">{{ row.total_amount }}</div>
        </template>

        <!-- PO Lines Column -->
        <template #body-cell-po_lines="{ row }">
          <div align="right" style="padding-right: 10px">{{ row.po_lines }}</div>
        </template>
      </DocBitsTable>
    </div>
  </div>

  <q-inner-loading :showing="loading" style="z-index: 1000000000;">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>

</template>
</template>

<script lang="ts">
import type { dynamicObj } from 'src/pages/assets';
import { storeToRefs } from 'pinia';
import { ref, defineComponent } from 'vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { getStatusColor } from 'src/pages/PurchaseOrders/constants.js';
import PoDashboardHeader from 'src/supplier/components/purchaseOrder/PoDashboardHeader.vue';
import { usePoAndInvoiceStore } from 'src/supplier/store';
import { ApiExceptions } from 'src/exceptions/index';
import { useAmountFormatStore, useSettingStore } from 'src/store/main';
import { purchase_order_dashboard_columns, CONSTANTS } from 'src/constants';
import dragDropColumn from 'src/mixins/dragDropColumn';
import MessageBanner from 'src/components/MessageBanner.vue';
import generateSavedColumns from 'src/utils/generateSavedColumns';
import dateUtils from 'src/utils/date';
import { notify } from 'src/components/notifications/notify';
import { DocBitsTable } from 'src/components/Table';
import { getSavedPaginationSize } from 'src/components/Table/PaginationSettings.vue';
import type {
  RowActionItem,
  SortEventPayload,
  PaginationChangePayload,
  RowActionPayload,
  RowClickPayload,
  UnifiedTableColumn,
} from 'src/components/Table';

export default defineComponent({
  mixins: [dragDropColumn, generateSavedColumns, dateUtils],
  props: {
    type_name: {
      type: String,
      reqired: true,
      default: 'supplier',
    },
  },
  components: {
    SubHeader,
    PoDashboardHeader,
    MessageBanner,
    DocBitsTable,
  },
  data() {
    return {
      pagination_settings_key: 'PO_PAGINATION_SIZE',
      show_table_loader: false,
      purchase_order_dashboard_columns,
      po_dashboard: CONSTANTS.po_dashboard,
    };
  },
  setup() {
    const dashboard_purchase_order_store = usePoAndInvoiceStore();

    const amount_format_store = useAmountFormatStore();
    const { formatMultiValues, searchValueByKey } = amount_format_store;

    const {
      display_data,
      loading,
      paginationCount,
      table_columns,
      params,
      pagination,
      order_by,
    } = storeToRefs(dashboard_purchase_order_store);
    const { getPurchaseOrderData, getSavedColumnPreference } = dashboard_purchase_order_store;

    const tableColumns = ref();
    tableColumns.value = Object.values(
      JSON.parse(JSON.stringify(table_columns.value)),
    ).map((column: any) => {
      return {
        name: column.name,
        required: true,
        label: column.translation_key,
        field: column.name,
        format: column.format,
        actions: column.actions,
        align: column.align,
      };
    });

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { updateSetting, startSettingsFetch } = settings_store;

    return {
      getPurchaseOrderData,
      getSavedColumnPreference,
      dashboard_purchase_order_store,
      display_data,
      loading,
      table_columns,
      tableColumns,
      paginationCount,
      params,
      total_records: ref(0),
      pagination,
      order_by,
      user_settings,
      amount_format_store,
      startSettingsFetch,
      formatMultiValues,
      searchValueByKey,
      updateSetting,
    };
  },
  computed: {
    /**
     * Table rows from store display_data
     */
    tableRows(): dynamicObj[] {
      return Object.values(this.display_data);
    },

    /**
     * V2 Table: Transform table_columns to UnifiedTableColumn format
     */
    v2TableColumns(): UnifiedTableColumn[] {
      if (!this.tableColumns || this.tableColumns.length === 0) {
        return [];
      }

      // Apply saved order from user_settings if available, otherwise use tableColumns order
      const savedColumnsStr = this.user_settings?.[this.purchase_order_dashboard_columns];
      let orderedColumns = this.tableColumns;

      if (savedColumnsStr && savedColumnsStr !== '') {
        try {
          const savedColumns = JSON.parse(savedColumnsStr);
          const orderMap = new Map(savedColumns.map((col: any, index: number) => [col.name, index]));
          orderedColumns = [...this.tableColumns].sort((a: any, b: any) => {
            const aIndex = orderMap.get(a.name) ?? 999;
            const bIndex = orderMap.get(b.name) ?? 999;
            return (aIndex as number) - (bIndex as number);
          });
        } catch {
          // Use tableColumns order
        }
      }

      return orderedColumns.map((col: any) => ({
        name: col.name,
        label: this.$t(col.label || col.name),
        field: col.name,
        sortable: col.actions === true,
        align: (col.name === 'total_amount' || col.name === 'po_lines')
          ? 'right' as const
          : (col.align || 'left') as 'left' | 'center' | 'right',
      }));
    },

    /**
     * V2 Table: Column order for persisted column reordering
     */
    v2ColumnOrder(): string[] {
      if (!this.tableColumns || this.tableColumns.length === 0) {
        return [];
      }

      // Apply saved order from user_settings if available
      const savedColumnsStr = this.user_settings?.[this.purchase_order_dashboard_columns];

      if (savedColumnsStr && savedColumnsStr !== '') {
        try {
          const savedColumns = JSON.parse(savedColumnsStr);
          return savedColumns.map((col: any) => col.name);
        } catch {
          // Use tableColumns order
        }
      }

      return this.tableColumns.map((col: any) => col.name);
    },

    /**
     * V2 Table: Feature configuration
     */
    v2TableFeatures() {
      return {
        sorting: true,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: true,
        columnReorder: true,
        columnSettings: true,
        stickyFirstColumn: false,
        stickyLastColumn: true,
      };
    },

    /**
     * V2 Table: Pagination state (includes sort info)
     */
    v2PaginationState() {
      let sortBy = null;
      let descending = false;

      if (this.order_by && Object.keys(this.order_by).length > 0) {
        const [col, dir] = Object.entries(this.order_by)[0];
        sortBy = col;
        descending = dir === 'desc';
      }

      return {
        sortBy,
        descending,
        page: this.pagination.current_page,
        rowsPerPage: this.pagination.page_size,
        rowsNumber: this.paginationCount || 0,
      };
    },

    /**
     * V2 Table: Row actions configuration
     */
    v2RowActions(): RowActionItem[] {
      return [
        { key: 'view', label: 'view', icon: 'visibility', color: 'primary' },
      ];
    },
  },
  mounted: function () {
    this.init();
    this.initDragDropColumns('purchase_order_table', 'label');
    document.addEventListener('purchase_order_table-column-drop', this.onDropColumns);
  },
  unmounted: function () {
    document.removeEventListener('purchase_order_table-column-drop', this.onDropColumns);
  },
  methods: {
    // ========== V2 Table Event Handlers ==========
    async handleV2Sort(payload: SortEventPayload) {
      if (payload.column && payload.direction) {
        this.dashboard_purchase_order_store.params.sort_by = payload.column;
        this.dashboard_purchase_order_store.params.order = payload.direction;
        this.dashboard_purchase_order_store.order_by = { [payload.column]: payload.direction };
      } else {
        this.dashboard_purchase_order_store.params.sort_by = '';
        this.dashboard_purchase_order_store.params.order = '';
        this.dashboard_purchase_order_store.order_by = {};
      }

      await this.getDataServer(true);
    },

    async handleV2Pagination(payload: PaginationChangePayload) {
      this.pagination.current_page = payload.page;
      this.pagination.page_size = payload.rowsPerPage;

      // Fetch data with new pagination
      await this.getDataServer(true);
    },

    handleV2RowClick(payload: RowClickPayload) {
      this.goToDetail(payload.row.id);
    },

    async handleV2ColumnReorder(columnNames: string[]) {
      const columnsToSave = columnNames.map((name) => {
        const col = this.tableColumns.find((c: any) => c.name === name);
        return col;
      }).filter(Boolean);

      // Update local state immediately (prevents flicker during save)
      this.tableColumns = columnsToSave;
      this.user_settings[this.purchase_order_dashboard_columns] = JSON.stringify(columnsToSave);

      // Save to backend
      await this.savedOrderColumns(columnsToSave);
    },

    handleV2RowAction(payload: RowActionPayload) {
      if (payload.action === 'view') {
        this.goToDetail(payload.row.id);
      }
    },
    // ========== End V2 Table Event Handlers ==========

    async init() {
      this.startSettingsFetch();
      this.pagination.page_size = await getSavedPaginationSize(this.pagination_settings_key);
      this.getDataServer(true);
      this.prepareTableColumns();
    },

    async getDataServer(show_table_loader: boolean) {
      try {
        this.loading = true;
        if (show_table_loader) {
          this.show_table_loader = true;
        }
        await this.getPurchaseOrderData();
        this.total_records = this.paginationCount;
      } catch (err) {
        logError(err);
      } finally {
        this.loading = false;
        this.show_table_loader = false;
      }
    },

    prepareTableColumns() {
      // Apply saved column order from user_settings if available
      const savedColumnsStr = this.user_settings?.[this.purchase_order_dashboard_columns];
      if (savedColumnsStr && savedColumnsStr !== '') {
        try {
          const savedColumns = JSON.parse(savedColumnsStr);
          // Reorder tableColumns based on saved order
          const orderMap = new Map(savedColumns.map((col: any, index: number) => [col.name, index]));
          this.tableColumns = [...this.tableColumns].sort((a: any, b: any) => {
            const aIndex = orderMap.get(a.name) ?? 999;
            const bIndex = orderMap.get(b.name) ?? 999;
            return (aIndex as number) - (bIndex as number);
          });
        } catch {
          // Keep default order if parsing fails
        }
      }
    },

    onDropColumns() {
      this.savedOrderColumns(this.tableColumns);
    },

    async savedOrderColumns(columns: any) {
      try {
        this.loading = true;
        await this.updateSetting(
          this.purchase_order_dashboard_columns,
          JSON.stringify(columns),
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    setRowStyle(row: any) {
      if (
        row.hasOwnProperty('export_data_fetched') &&
        row['export_data_fetched'] === true
      ) {
        return 'exported-row';
      }
    },

    paginationItemClicked() {
      try {
        this.getDataServer(true);
      } catch (error) {
        logError(error);
      }
    },

    // click view detail purchase order details
    goToDetail(purchase_number: string | number) {
      this.$router.push(`/purchase-order-detail/${purchase_number}`);
    },

    statusColor(status: string) {
      return getStatusColor(status.toLowerCase()) || 'primary';
    },
  },
});
</script>

<style scoped lang="scss">
// Styles inherited from dashboard-table-style in app.scss
</style>
